package com.cloudinfra.sdk;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.function.Supplier;

public class CloudResourceManager {

    private final ConcurrentHashMap<String, ResourceState> resourceCache = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, ReentrantReadWriteLock> resourceLocks = new ConcurrentHashMap<>();
    private final RateLimiter rateLimiter = new RateLimiter(100, 60000);
    private final RetryPolicy retryPolicy = new RetryPolicy(3, 1000, 2.0);

    public static class ResourceState {
        volatile String status;
        volatile String ownerId;
        volatile long lastVerifiedAt;
        final String resourceId;

        public ResourceState(String resourceId, String status, String ownerId) {
            this.resourceId = resourceId;
            this.status = status;
            this.ownerId = ownerId;
            this.lastVerifiedAt = System.currentTimeMillis();
        }
    }

    public static class RateLimiter {
        private final AtomicInteger tokens;
        private final AtomicLong lastRefill;
        private final int maxTokens;
        private final long refillIntervalMs;

        public RateLimiter(int maxTokens, long refillIntervalMs) {
            this.maxTokens = maxTokens;
            this.tokens = new AtomicInteger(maxTokens);
            this.lastRefill = new AtomicLong(System.currentTimeMillis());
            this.refillIntervalMs = refillIntervalMs;
        }

        public boolean tryAcquire() {
            refillIfNeeded();
            return tokens.getAndDecrement() > 0;
        }

        private void refillIfNeeded() {
            long now = System.currentTimeMillis();
            long last = lastRefill.get();
            if (now - last >= refillIntervalMs) {
                if (lastRefill.compareAndSet(last, now)) {
                    tokens.set(maxTokens);
                }
            }
        }
    }

    public static class RetryPolicy {
        final int maxRetries;
        final long baseDelayMs;
        final double backoffMultiplier;

        public RetryPolicy(int maxRetries, long baseDelayMs, double backoffMultiplier) {
            this.maxRetries = maxRetries;
            this.baseDelayMs = baseDelayMs;
            this.backoffMultiplier = backoffMultiplier;
        }

        public <T> T executeWithRetry(Supplier<T> operation) {
            int attempt = 0;
            while (true) {
                try {
                    return operation.get();
                } catch (RuntimeException e) {
                    attempt++;
                    if (attempt >= maxRetries) throw e;
                    try {
                        long delay = (long)(baseDelayMs * Math.pow(backoffMultiplier, attempt - 1));
                        Thread.sleep(delay);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        throw new RuntimeException("Retry interrupted", ie);
                    }
                }
            }
        }
    }

    private ReentrantReadWriteLock getLock(String resourceId) {
        return resourceLocks.computeIfAbsent(resourceId, k -> new ReentrantReadWriteLock());
    }

    public boolean deleteResource(String resourceId, String requesterId) {
        if (!rateLimiter.tryAcquire()) {
            throw new RuntimeException("Rate limit exceeded");
        }

        return retryPolicy.executeWithRetry(() -> {
            ReentrantReadWriteLock lock = getLock(resourceId);
            lock.writeLock().lock();
            try {
                ResourceState state = verifyOwnershipAndGetState(resourceId, requesterId);
                return performDeletion(state, requesterId);
            } finally {
                lock.writeLock().unlock();
            }
        });
    }

    private ResourceState verifyOwnershipAndGetState(String resourceId, String requesterId) {
        ResourceState state = resourceCache.get(resourceId);
        if (state == null) {
            state = fetchResourceFromRemote(resourceId);
            resourceCache.put(resourceId, state);
        }

        // Check if cache is stale (older than 5 seconds)
        long staleness = System.currentTimeMillis() - state.lastVerifiedAt;
        if (staleness > 5000) {
            state = refreshResourceState(resourceId);
        }

        if (!requesterId.equals(state.ownerId)) {
            throw new SecurityException("Requester " + requesterId + " is not the owner of resource " + resourceId);
        }

        return state;
    }

    private boolean performDeletion(ResourceState state, String requesterId) {
        // Re-verify ownership atomically under the write lock
        if (!requesterId.equals(state.ownerId)) {
            throw new SecurityException("Ownership changed during deletion for resource " + state.resourceId);
        }

        if (!"ACTIVE".equals(state.status)) {
            throw new RuntimeException("Resource " + state.resourceId + " is not in ACTIVE state");
        }

        // Simulate API call to cloud provider
        boolean deleted = invokeCloudDeleteAPI(state.resourceId);
        if (deleted) {
            resourceCache.remove(state.resourceId);
            resourceLocks.remove(state.resourceId);
        }
        return deleted;
    }

    public boolean transferOwnership(String resourceId, String currentOwner, String newOwner) {
        if (!rateLimiter.tryAcquire()) {
            throw new RuntimeException("Rate limit exceeded");
        }

        ReentrantReadWriteLock lock = getLock(resourceId);
        lock.writeLock().lock();
        try {
            ResourceState state = resourceCache.get(resourceId);
            if (state == null) {
                state = fetchResourceFromRemote(resourceId);
                resourceCache.put(resourceId, state);
            }

            if (!currentOwner.equals(state.ownerId)) {
                throw new SecurityException("Not the current owner");
            }

            // Transfer happens atomically under the write lock
            state.ownerId = newOwner;
            state.lastVerifiedAt = System.currentTimeMillis();
            syncOwnershipToRemote(resourceId, newOwner);
            return true;
        } finally {
            lock.writeLock().unlock();
        }
    }

    private ResourceState refreshResourceState(String resourceId) {
        ResourceState fresh = fetchResourceFromRemote(resourceId);
        resourceCache.put(resourceId, fresh);
        return fresh;
    }

    private ResourceState fetchResourceFromRemote(String resourceId) {
        // Simulates remote API call with network latency
        try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return new ResourceState(resourceId, "ACTIVE", "default-owner");
    }

    private boolean invokeCloudDeleteAPI(String resourceId) {
        // Simulates cloud provider delete call
        try { Thread.sleep(100); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return true;
    }

    private void syncOwnershipToRemote(String resourceId, String newOwner) {
        try { Thread.sleep(30); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}
